import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the versioned golden vectors generated by `viamin/color_matching`.
///
/// The fixture is copied from `priv/parity/v1/corpus.json` in the backend so
/// scorer semantics cannot drift on weighting, exclusions, or tie-breaking.
final class SolverParityCorpusTests: XCTestCase {
    func testCorpusMetadataDescribesSupportedSolverContract() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
        XCTAssertFalse(corpus.scenarios.isEmpty)
        XCTAssertTrue(corpus.scenarios.contains { $0.expected.tieBroke == true })
    }

    func testWeightedSquaredErrorMatchesCommittedParityCorpus() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario.weights)
            let target = TargetResponseVector(makeChannels(scenario.target.channels))
            let palette = scenario.palette
                .sorted { $0.index < $1.index }
                .map(makePaletteColor)
            let expected = scenario.expected
            let results = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }

            XCTAssertEqual(results.count, expected.scores.count, scenario.id)
            for (result, score) in zip(results, expected.scores.sorted { $0.index < $1.index }) {
                assert(result, matches: score.score, scenarioID: scenario.id)
            }

            let eligible = results.enumerated().compactMap { index, result -> (Int, Double)? in
                guard case .score(let value) = result else { return nil }
                return (index, value)
            }
            let bestError = eligible.map(\.1).min()
            let tiedIndices = eligible.compactMap { index, value in
                value == bestError ? index : nil
            }

            XCTAssertEqual(tiedIndices, expected.tiedIndices, scenario.id)
            XCTAssertEqual(tiedIndices.count > 1, expected.tieBroke ?? false, scenario.id)

            guard let selectedIndex = expected.selectedIndex else {
                XCTAssertNil(bestError, scenario.id)
                XCTAssertNil(expected.error, scenario.id)
                continue
            }

            XCTAssertEqual(tiedIndices.first, selectedIndex, scenario.id)
            XCTAssertEqual(bestError, expected.error, scenario.id)
            XCTAssertEqual(palette[selectedIndex].hex, expected.selectedHexColor, scenario.id)
        }
    }

    func testCompositionSolverMatchesCorpusSelectionsWhenTargetIsComplete() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario.weights)
            guard let grids = makeSourceGrids(target: scenario.target, weights: weights) else {
                XCTAssertNil(scenario.expected.selectedIndex, scenario.id)
                continue
            }

            let palette = scenario.palette
                .sorted { $0.index < $1.index }
                .map(makePaletteColor)
            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids,
                weights: weights
            )

            XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, scenario.id)
            XCTAssertEqual(result.errors[0], scenario.expected.error ?? .infinity, accuracy: 0, scenario.id)
            XCTAssertEqual(result.excludedCandidateCount, scenario.expected.scores.filter { $0.score == .excluded }.count, scenario.id)
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/SolverParity/v1/corpus.json")
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: fixture))
    }

    private func makeWeights(_ values: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: values[LightingCondition.white.rawValue] ?? 0,
            red: values[LightingCondition.red.rawValue] ?? 0,
            green: values[LightingCondition.green.rawValue] ?? 0,
            blue: values[LightingCondition.blue.rawValue] ?? 0,
            lps: values[LightingCondition.lps.rawValue] ?? 0
        )
    }

    private func makeChannels(_ values: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: LightingCondition.all.compactMap { condition in
            values[condition.rawValue].map { (condition, $0) }
        })
    }

    private func makePaletteColor(_ vector: ParityCorpus.Vector) -> PaletteColor {
        PaletteColor(
            id: vector.index ?? 0,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor)!,
            responses: makeChannels(vector.channels).mapValues { IlluminationResponse(brightness: $0) }
        )
    }

    private func makeSourceGrids(
        target: ParityCorpus.Vector,
        weights: ChannelWeights
    ) -> [LightingCondition: BrightnessGrid]? {
        var grids: [LightingCondition: BrightnessGrid] = [:]
        for (condition, _) in weights.activeEntries {
            guard let value = target.channels[condition.rawValue] else { return nil }
            grids[condition] = BrightnessGrid(width: 1, height: 1, values: [value])
        }
        return grids
    }

    private func assert(
        _ result: ScorerResult,
        matches expected: ParityCorpus.Score,
        scenarioID: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        switch (result, expected) {
        case (.excluded, .excluded):
            break
        case (.score(let actual), .value(let value)):
            XCTAssertEqual(actual, value, accuracy: 0, scenarioID, file: file, line: line)
        default:
            XCTFail("\(scenarioID): scorer result did not match corpus", file: file, line: line)
        }
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [Scenario]

    struct Scenario: Decodable {
        let id: String
        let weights: [String: Double]
        let target: Vector
        let palette: [Vector]
        let expected: Expected
    }

    struct Vector: Decodable {
        let channels: [String: Double]
        let hexColor: String
        let index: Int?

        private enum CodingKeys: String, CodingKey {
            case channels
            case hexColor = "hex_color"
            case index
        }
    }

    struct Expected: Decodable {
        let error: Double?
        let scores: [IndexedScore]
        let selectedHexColor: String?
        let selectedIndex: Int?
        let tieBroke: Bool?
        let tiedIndices: [Int]

        private enum CodingKeys: String, CodingKey {
            case error
            case scores
            case selectedHexColor = "selected_hex_color"
            case selectedIndex = "selected_index"
            case tieBroke = "tie_broke"
            case tiedIndices = "tied_indices"
        }
    }

    struct IndexedScore: Decodable {
        let index: Int
        let score: Score
    }

    enum Score: Equatable, Decodable {
        case excluded
        case value(Double)

        init(from decoder: Decoder) throws {
            let container = try decoder.singleValueContainer()
            if let value = try? container.decode(Double.self) {
                self = .value(value)
            } else if try container.decode(String.self) == "excluded" {
                self = .excluded
            } else {
                throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
            }
        }
    }

    private enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case scorer
        case selection
        case missingPolicy = "missing_policy"
        case lightSources = "light_sources"
        case scenarios
    }
}
